 if(targetIndex>=0){const start=b.chords[targetIndex].start,end=b.chords[targetIndex+1]?.start??meterUnits(b)+1;next.forEach((c,i)=>c.start=start+i*(end-start)/next.length);const step=denominator(b)/resolution;if(next.some(c=>Math.abs((c.start-1)/step-Math.round((c.start-1)/step))>.001)){draft.error='Bytena ryms inte på valt rutnät. Välj hela takten eller ändra placeringen i Ändra ackord.';renderScore();if(d.kind==='panel'&&$('#panel-chord-feedback'))$('#panel-chord-feedback').textContent=draft.error;focusDraft(false);return false;}}
