function commitRename(){if(!renameState)return true;const part=sectionById(renameState.id),value=($('#part-name')?.value??renameState.value).trim();if(!value||value.length>80||model.sections.some(s=>s.id!==part.id&&s.name.toLocaleLowerCase('sv')===value.toLocaleLowerCase('sv'))){renameState.value=value;renameState.error=!value?'Skriv ett namn för delen.':'Välj ett eget namn, högst 80 tecken.';renderScore();$('#part-name')?.focus();return false;}renameState=null;if(part.name===value){render();return true;}mutate(()=>part.name=value,'Delens namn uppdaterades även i låtformen.');return true;}
