function positionChordTools(){for(const row of document.querySelectorAll('.score-row')){const base=innerWidth<761?87:85;let needed=base;for(const variant of row.querySelectorAll('.variant'))needed=Math.max(needed,variant.offsetTop+variant.scrollHeight+13);row.style.setProperty('--bar-needed-height',needed+'px');}const tools=$('.chord-tools');if(!tools)return;const b=tools.closest('.bar'),bounds=b.getBoundingClientRect(),scene=$('.scene').getBoundingClientRect(),width=tools.getBoundingClientRect().width,x=bounds.left;tools.style.left=(Math.max(scene.left+8,Math.min(x,scene.right-width-8))-bounds.left)+'px';}
function addRecent(name){if(!needBar())return;const b=selectedBar();if(b.chords.length>=4)return fail('Högst fyra ackord ryms i denna mockups takt.');const anchor=b.chords.find(c=>c.id===chordId),index=anchor?b.chords.indexOf(anchor)+1:b.chords.length,previous=b.chords[index-1],end=b.chords[index]?.start??meterUnits(b)+1;let start=!previous?1:positions(b).find(n=>n>previous.start&&n<end);if(b.chords.length===1&&index===1&&previous.start===1&&meterUnits(b)>=3&&end>3)start=3;if(start==null)return fail('Ingen ledig startpunkt efter ackordet på valt rutnät. Välj ett finare notvärde.');mutate(()=>{const c={id:++uid,name,parenthetical:false,start,variant:''};b.chords.splice(index,0,c);chordId=c.id;model.recent=[name,...model.recent.filter(v=>v!==name)].slice(0,8);},name+' lades till på slag '+beatLabel(start)+'.');}

function duplicateBars(ids){const section=sectionOf(ids[0]),index=section.bars.findIndex(b=>b.id===ids.at(-1));mutate(()=>{const spans=section.bars.filter(b=>b.houseSpan).map(owner=>({owner,first:owner.houseSpan.barIds[0],last:owner.houseSpan.barIds.at(-1)}));const bars=ids.map(id=>{const b=clone(barById(id));b.id=++uid;b.houseSpan=null;b.repeatStart=false;b.repeatEnd=false;b.rowBreak=false;b.pageBreak=false;b.chords.forEach(c=>c.id=++uid);return b;});section.bars.splice(index+1,0,...bars);for(const span of spans){const first=section.bars.findIndex(b=>b.id===span.first),last=section.bars.findIndex(b=>b.id===span.last);span.owner.houseSpan.barIds=section.bars.slice(first,last+1).map(b=>b.id);span.owner.houseSpan.length=span.owner.houseSpan.barIds.length;}selected=bars.map(b=>b.id);chordId=null;},'Kopian infogades efter markeringen. Repristecken och radbrytningar kopieras inte.');}
function applyHouse(number){mutate(()=>{visibleBars().filter(b=>b.houseSpan?.barIds.some(id=>selected.includes(id))).forEach(b=>b.houseSpan=null);barById(selected[0]).houseSpan={number,length:selected.length,barIds:[...selected]};pendingHouse=null;},'Huset visas över markerade takter.');}
function variantDecisionHTML(){return draft?.variantChanges?`<section class="variant-review"><h3>Variantackord behöver ett val</h3>${draft.variantChanges.map(c=>`<p class="hint">${esc(c.before)} blir ${esc(c.after)}. Varianten är ${esc(c.variant)}.</p>`).join('')}<p class="hint">Ingen ändring sparas förrän du väljer.</p><div class="options">${opt('Ta bort berörda varianter','variant-choice:remove')}${opt('Behåll berörda varianter','variant-choice:keep')}${opt('Återgå till texten','variant-choice:edit')}</div></section>`:'';}
function settingsBody(){return `<section><h3>När ackord öppnas för redigering</h3><label class="preference-option"><input type="radio" name="text-behavior" value="caret" ${preferences.selectAll?'':'checked'}> Skrivmarkör för små rättningar</label><label class="preference-option"><input type="radio" name="text-behavior" value="select" ${preferences.selectAll?'checked':''}> Markera all text i det öppnade fältet</label><p class="hint">Första klicket markerar ett ackord. Nästa klick på samma ackord öppnar taktens ackordrad. Klick i tom ackordyta öppnar raden direkt. Inställningen sparas i denna webbläsare.</p></section><section><h3>Markera takter</h3><p class="hint">Klicka på raden med taktnummer. För ett spann väljer du första takten, Markera flera och sedan sista takten.</p></section>`;}
function detachReuse(){const block=selectedForm(),source=sectionById(block.source);if(!block?.reuse)return;mutate(()=>{const copy=clone(source),ids=new Map();copy.id='part'+(++uid);let n=1;while(model.sections.some(s=>s.name===source.name+' · egen '+n))n++;copy.name=source.name+' · egen '+n;copy.bars.forEach(b=>{const old=b.id;b.id=++uid;ids.set(old,b.id);b.chords.forEach(c=>c.id=++uid);});copy.bars.forEach(b=>{if(b.houseSpan)b.houseSpan.barIds=b.houseSpan.barIds.map(id=>ids.get(id));});if(copy.bars.length&&!copy.bars[0].meter)copy.bars[0].meter=copy.entryMeter||meterFor(source.bars[0]);model.sections.push(copy);block.source=copy.id;block.reuse=false;selected=copy.bars.length?[copy.bars[0].id]:[];chordId=null;},'Delen är nu självständig. Antal gånger och anvisning är kvar.');}
function houseMarker(b){const section=sectionOf(b.id),start=section.bars.find(v=>v.houseSpan?.barIds.includes(b.id));if(!start)return '';const span=start.houseSpan,index=span.barIds.indexOf(b.id),row=scoreRowData(section).find(r=>r.some(v=>v.id===b.id)),col=row.findIndex(v=>v.id===b.id);if(index>0&&col>0)return '';let cells=0;while(col+cells<row.length&&row[col+cells].id===span.barIds[index+cells])cells++;const end=index+cells===span.barIds.length;return `<span class="marker" style="width:calc(${cells*100}% + ${cells-1}px);${end?'border-right:1px solid var(--ink)':''}">${index===0?esc(span.number)+'.':''}</span>`;}
function scoreBar(b){
 const selectedClass=selected.includes(b.id)?'selected':'';const editing=draft?.barId===b.id&&draft.kind!=='panel';
 return `<div class="bar ${selectedClass} ${editing?'editing':''} ${b.repeatStart?'repeat-start':''} ${b.repeatEnd?'repeat-end':''}" data-bar="${b.id}" tabindex="0" role="group" aria-label="Takt ${numberOf(b.id)}, ${esc(serialize(b)||'tom')}"><button class="bar-number" data-select-bar="${b.id}" aria-label="Markera takt ${numberOf(b.id)}" title="Markera takt ${numberOf(b.id)}">${numberOf(b.id)}</button>${houseMarker(b)}${b.rowBreak||b.pageBreak?`<span class="break-marker">${b.pageBreak?'Sidbrytning':'Radbrytning'}</span>`:''}${b.key||b.meter?`<span class="bar-change">${esc([b.key,b.meter].filter(Boolean).join(' · '))}</span>`:''}${`<div class="chord-area" data-chord-area="${b.id}" role="button" tabindex="0" aria-label="Redigera ackordraden i takt ${numberOf(b.id)}"></div>`}${b.chords.map(c=>`<span class="chord ${chordId===c.id&&!draft?'chord-selected':''}" data-chord="${c.id}" style="left:${8+(c.start-1)/meterUnits(b)*88}%" role="button" tabindex="0" aria-pressed="${chordId===c.id&&!draft}" aria-label="Markera ${esc(c.name)} i takt ${numberOf(b.id)}; klicka igen för att redigera ackordraden">${esc(c.parenthetical?'('+c.name+')':c.name)}</span>`).join('')}${b.chords.some(c=>c.variant)?`<div class="variant">${b.chords.filter(c=>c.variant).map(c=>`<div>${esc(variantLabel(c))}</div>`).join('')}</div>`:''}${b.attacks.length?`<div class="rhythm-line">${b.attacks.map(a=>`<span class="beat-tick" title="Anslag ${beatLabel(a.start)}, notvärde 1/${a.duration}">${beatLabel(a.start)}</span>`).join('')}</div>`:''}${barActions(b)}${chordTools(b)}${editing?`<input id="score-edit" class="score-edit" aria-label="Skriv ackord direkt i takt ${numberOf(b.id)}" value="${esc(draft.value)}" autocomplete="off" spellcheck="false">${draft.chordId?'':`<span class="editing-help">Hela takten · Mellanslag = nytt · Enter = klart</span>`}${draft.error?`<div class="score-error" role="alert">${esc(draft.error)}</div>`:''}`:''}</div>`;
}
function scoreRowData(s){let rows=[],row=[];for(const b of s.bars){if((b.rowBreak||b.pageBreak)&&row.length){rows.push(row);row=[];}row.push(b);if(row.length===4){rows.push(row);row=[];}}if(row.length)rows.push(row);return rows;}
function scoreRows(s){return scoreRowData(s).map(r=>`<div class="score-row ${r[0].pageBreak?'page-start':''}" style="--variant-lines:${Math.max(...r.map(b=>b.chords.filter(c=>c.variant).length))}">${r.map(scoreBar).join('')}</div>`).join('');}
function scoreHTML(){return `<h2 class="paper-title">${esc(model.title)}</h2><div class="credits"><span>${esc(model.artist)}</span><span>${esc(model.key)} · ${esc(model.meter)} · ${model.tempo} bpm</span></div>${!model.form.length?'<div class="empty-score">Inga delar kvar. Ångra återställer den senaste borttagningen.</div>':''}${model.form.map(block=>{const s=sectionById(block.source);if(block.reuse)return `<div class="reuse-score" data-score-block="${block.id}"><strong>${esc(s.name)} × ${block.count}</strong><p>Återanvänd del · följer originalets ackord${block.instruction?' · '+esc(block.instruction):''}</p>${btn('Visa originaldelen', 'goto-source:'+s.id)}</div>`;return `<section class="score-section ${selectedPart===s.id?'part-selected':''}" id="section-${s.id}" data-score-block="${block.id}"><div class="section-title">${renameState?.id===s.id?`<input id="part-name" aria-label="Delens namn" maxlength="80" value="${esc(renameState.value)}">${btn('Spara','part-rename-save','outline')}${btn('Avbryt','part-rename-cancel')}${renameState.error?`<span class="title-error" role="alert">${esc(renameState.error)}</span>`:''}`:btn(`${esc(s.name)}${block.count>1?' × '+block.count:''}`,'select-part:'+s.id,'part-name',`aria-pressed="${selectedPart===s.id}" title="Markera hela delen"`)}<span>${s.bars.length} takter${block.instruction?' · '+esc(block.instruction):''}</span>${selectedPart===s.id&&!renameState?`<div class="part-actions">${btn('Ändra titel','rename-part:'+s.id,'outline')}${btn('×','delete-part:'+s.id,'part-delete',`aria-label="Ta bort delen ${esc(s.name)}" title="Ta bort delen ${esc(s.name)}"`)}</div>`:''}</div>${scoreRows(s)}</section>`;}).join('')}`;}
function renderScore(){const saved=captureFocus(),paper=$('.paper'),scroll=$('.scene')?.scrollTop||0;if(paper)paper.innerHTML=scoreHTML();if($('.scene'))$('.scene').scrollTop=scroll;restoreFocus(saved);positionChordTools();}
function changeStartsHTML(b){if(!b?.chords.length)return '<p class="hint">Skriv ackord i takten först.</p>';return `<h3>Ordning på ackordsbyten</h3><p class="hint">Startpunkterna går från vänster till höger.</p>${b.chords.map((c,i)=>`<div class="beat-row"><span class="name" title="${esc(c.name)}">${esc(c.name)}</span><select aria-label="${esc(c.name)} börjar på" data-start="${c.id}">${[...new Set([...positions(b),c.start])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${n===c.start?'selected':''}>Slag ${beatLabel(n)}</option>`).join('')}</select>${btn('↑','chord-up:'+c.id,'',`aria-label="Flytta ${esc(c.name)} före föregående ackord" ${i===0?'disabled':''}`)}</div>`).join('')}`;}
function resolutionHTML(){return `<label class="eyebrow">Placera på</label><div class="resolution">${[4,8,16].map(n=>btn('1/'+n+'-delar','resolution:'+n,n===resolution?'active':'')).join('')}</div><p class="hint">Rutnät för startpunkter. Anslagens notvärden väljs separat.</p>`;}
function localChangesHTML(){return `<section><h3>Byten i markerad takt</h3><div class="two"><div class="field"><label for="local-key">Tonart</label><select id="local-key"><option value="">Inget byte</option>${['C','D','E','F','G','A','Bb','Bm','Dm','Em'].map(v=>`<option ${selectedBar()?.key===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="local-meter">Taktart</label><select id="local-meter"><option value="">Inget byte</option>${['4/4','3/4','6/8'].map(v=>`<option ${selectedBar()?.meter===v?'selected':''}>${v}</option>`).join('')}</select></div></div>${btn('Använd byten','local-apply','outline',selected.length===1?'':'disabled')}<p class="hint">Bytet börjar vid taktens första slag.</p></section>`;}
function musicBody(){const b=selectedBar(),c=currentChord();
 if(tool==='chord')return `<section><h3>Ackord i markerad takt</h3>${field('Ackord','panel-chords',draft?.kind==='panel'?draft.value:b?serialize(b):'','placeholder="Till exempel D A" '+(b?'':'disabled'))}<p class="hint">Mellanslag lägger till ackord. Parenteser skrivs direkt. Enter eller klick utanför sparar.</p><div id="panel-chord-feedback" class="hint" role="status">${draft?.kind==='panel'?esc(draft.error||''):''}</div></section><section><h3>Tidigare ackord</h3><div class="chips">${model.recent.map(n=>btn(esc(n),'recent:'+n,'',b?'':'disabled')).join('')}</div><p class="hint">Läggs till efter markerat ackord, eller sist i takten.</p>${btn('N.C.','nc','outline',b?'':'disabled')}</section><section><h3>Variantackord</h3>${field('Alternativ till '+(c?.name||'markerat ackord'),'variant',c?.variant||'','placeholder="Till exempel G Am" '+(c?'':'disabled'))}<div class="two">${field('Spelas gången','variant-pass',c?.variantPass||2,'type="number" min="2" max="16" '+(c?'':'disabled'))}${field('Stämma, valfritt','variant-voice',c?.variantVoice||'')}</div><label class="row small"><input type="checkbox" id="variant-following" ${c?.variantFollowing?'checked':''}> Även följande gånger</label><p class="hint variant-description">Skriv flera ackord med mellanslag. Giltiga ändringar uppdateras direkt.</p><div id="variant-feedback" class="hint" role="status">${c?.variant?esc(variantLabel(c)):'Tomt fält tar bort varianten.'}</div></section><section>${resolutionHTML()}${changeStartsHTML(b)}</section>`;
 if(tool==='rhythm')return `<section>${resolutionHTML()}${changeStartsHTML(b)}</section><section><h3>Anslag i ${b?meterFor(b):'markerad takt'}</h3><p class="hint">Klicka på en startpunkt. Varje anslag får ett eget notvärde.</p>${b?`<div class="beat-grid">${Array.from({length:meterUnits(b)},(_,beat)=>`<div class="beat-group"><span>Slag ${beat+1}</span>${positions(b).filter(n=>Math.floor(n)===beat+1).map(n=>btn(beatLabel(n),'attack:'+n,b.attacks.some(a=>a.start===n)?'on':'',`aria-label="Anslag på ${beatLabel(n)}" aria-pressed="${b.attacks.some(a=>a.start===n)}"`)).join('')}</div>`).join('')}</div><div class="attacks">${b.attacks.sort((a,z)=>a.start-z.start).map(a=>`<div class="beat-row"><span>${beatLabel(a.start)}</span><select data-duration="${a.start}" aria-label="Notvärde för anslag ${beatLabel(a.start)}">${[4,8,16].map(n=>`<option value="${n}" ${a.duration===n?'selected':''}>1/${n}</option>`).join('')}</select>${btn('×','attack:'+a.start,'',`aria-label="Ta bort anslag ${beatLabel(a.start)}"`)}</div>`).join('')}</div>`:'<div class="notice">Välj en takt i bladet för att ange anslag.</div>'}</section>`;
 if(tool==='repeats')return `<section><h3>Repris</h3><div class="options">${opt('Repris runt markeringen','repeat:both','Start i första takten, slut i sista')}${opt('Bara reprisstart','repeat:start')}${opt('Bara reprisslut','repeat:end')}</div></section><section><h3>Hus</h3><div class="two">${btn('Första hus','house:1','outline')}${btn('Andra hus','house:2','outline')}</div><div class="options" style="margin-top:8px">${opt('Eget hus…','house:custom','Välj eget nummer och granska spannet')}${opt('Ta bort hus i markeringen','house-remove')}</div></section>`;
 if(tool.startsWith('house')){const number=tool.split(':')[1]||'1';return `${btn('← Tillbaka till Repris & hus','tool:repeats','back-button')}<section>${field('Husnummer','house-number',number==='custom'?'1, 2':number)}<div class="notice">Gäller ${selectionText()}. Markera med taktnummerraden och Markera flera.</div><p class="hint">Hus läggs på markerade takter. Repristecken ändras separat.</p>${btn('Lägg till hus','house-apply','primary',selected.length?'':'disabled')}</section>`;}
 if(tool==='insert')return `<section><h3>Innehåll</h3><div class="options">${opt('Skriv ackord i takten','continue-edit','Klicka också direkt i bladet för att skriva')}${opt('Ny tom takt efter markeringen','insert-bar')}${opt('Duplicera markerade takter','duplicate-bars')}</div></section>${localChangesHTML()}`;
 if(tool==='layout')return `<section><h3>Rad och sida</h3><div class="options">${opt('Radbrytning före vald takt','break:row','Ny rad från markeringen')}${opt('Sidbrytning före vald takt','break:page','Visar en tydlig ny sida i mockupen')}${opt('Ta bort brytning','break:remove')}</div></section>`+localChangesHTML();
 return `<section><h3>Redigera direkt i bladet</h3><p class="hint">Klicka på ett ackord för att markera det. Klicka igen för att redigera hela ackordraden. Tomt utrymme i ackordraden öppnar skrivfältet direkt.</p><div class="notice">D A → två ackord<br>(D A) → båda inom parentes<br>Taktnummerrad → markera takten</div></section><section><h3>Verktyg</h3><div class="options">${opt('Ändra ackord','tool:chord','Tidigare ackord, N.C., varianter och byten')}${opt('Infoga','tool:insert','Takter, tonartsbyte och taktartsbyte')}${opt('Rytm','tool:rhythm','4-delar, 8-delar och 16-delar')}${opt('Repris & hus','tool:repeats','Repristecken och numrerade hus')}${opt('Layout','tool:layout','Lokala byten')}</div></section>`;
}
function formBody(){const block=selectedForm(),s=block?sectionById(block.source):null;return `<section><h3>Hela låtens form</h3><p class="hint">Klicka på en del. Flytta block upp eller ner för att ändra ordningen.</p><div class="form-list">${model.form.map((f,i)=>`<div class="form-block ${f.id===selectedBlock?'selected':''} ${f.reuse?'reuse':''}" data-block="${f.id}" draggable="true"><span class="drag-hint" aria-hidden="true">⋮⋮</span><span class="block-index">${String(i+1).padStart(2,'0')}</span>${btn(`<strong>${esc(sectionById(f.source).name)}${f.count>1?' × '+f.count:''}</strong><small>${f.reuse?'Återanvänd del · länkad':sectionById(f.source).bars.length+' takter'}${f.instruction?' · '+esc(f.instruction):''}</small>`,'block:'+f.id,'select-block',`aria-pressed="${f.id===selectedBlock}"`)}<div class="moves">${btn('↑','move:'+f.id+':-1','',`aria-label="Flytta block ${i+1} upp" ${i===0?'disabled':''}`)}${btn('↓','move:'+f.id+':1','',`aria-label="Flytta block ${i+1} ner" ${i===model.form.length-1?'disabled':''}`)}</div></div>`).join('')}</div><p class="reorder-note">Dra blocket eller använd pilarna. Återanvändningar kan placeras före och efter originaldelen.</p></section>${block&&!block.reuse?`<section><h3>${esc(s.name)}</h3><p class="hint">${s.bars.length} takter${block.count>1?' · spelas '+block.count+' gånger':''}${block.instruction?' · '+esc(block.instruction):''}. Ändringar i originaldelen följer med till alla återanvändningar.</p>${btn('Återanvänd','reuse','primary')}${btn('Visa i bladet','goto-source:'+s.id,'outline')}</section>`:''}${block?.reuse?`<section class="reuse-settings"><h3>Återanvänd del</h3><div class="context-pill">${esc(s.name)} · följer originaldelen</div>${field('Antal gånger','reuse-count',block.count,'type="number" min="1" max="16"')}${field('Anvisning','reuse-instruction',block.instruction,'placeholder="Till exempel instrumentalt"')}${btn('Använd inställningar','reuse-apply','primary')}<p class="hint">Markeringens färg och text visar att delen återanvänds. Flytta den genom att flytta blocket ovanför.</p>${btn('Visa originaldelen','goto-source:'+s.id,'outline')}${btn('Gör till egen del','detach-reuse','outline')}${btn('Ta bort återanvändning','reuse-remove','outline')}</section>`:''}`;}
function songBody(){return `<section>${field('Titel','song-title',model.title)}${field('Artist','song-artist',model.artist)}<div class="two">${field('Grundtonart','song-key',model.key)}${field('Tempo','song-tempo',model.tempo,'type="number" min="20" max="300"')}</div><div class="two"><div class="field"><label for="song-meter">Grundtaktart</label><select id="song-meter">${['4/4','3/4','6/8'].map(v=>`<option ${v===model.meter?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="song-status">Status</label><select id="song-status">${['Arbetsutkast','Granskad'].map(v=>`<option ${v===model.status?'selected':''}>${v}</option>`).join('')}</select></div></div>${field('Version','song-version',model.version)}${btn('Använd låtuppgifter','song-apply','primary')}</section><p class="hint">Låtuppgifter och form finns alltid på sina egna flikar. Textfilen är gömd i det föreslagna redigeringsläget.</p>`;}
function panelHTML(){const heading=tab==='settings'?'Inställningar':tab==='form'?'Låtform':tab==='song'?'Låtuppgifter':({'chord':'Ändra ackord','rhythm':'Rytm och ackordsbyten','repeats':'Repris & hus','insert':'Infoga','layout':'Layout'})[tool]||(tool.startsWith('house')?'Hus':'Musik');return `<div class="panel-nav" role="tablist" aria-label="Verktygsgrupper">${[['music','Musik'],['form','Form'],['song','Låt']].map(([id,label])=>btn(label,'tab:'+id,tab===id?'active':'',`role="tab" aria-selected="${tab===id}"`)).join('')}${btn('×','close-panel','sheet-close','aria-label="Stäng verktyg"')}</div><div class="panel-heading"><h2>${heading}</h2><p class="context">${tab==='music'?selectionText():esc(model.title)+' · hela arrangemanget'}</p></div><div class="panel-body">${variantDecisionHTML()}${tab==='settings'?settingsBody():tab==='music'?musicBody():tab==='form'?formBody():songBody()}${pendingHouse?`<section class="house-conflict"><h3>Husen överlappar</h3><p class="hint">Nytt hus ${esc(pendingHouse.number)}: takt ${numberOf(selected[0])} till ${numberOf(selected.at(-1))}.</p>${pendingHouse.spans.map(span=>`<p class="hint">Befintligt hus ${esc(span.number)}: takt ${numberOf(span.barIds[0])} till ${numberOf(span.barIds.at(-1))}.</p>`).join('')}${btn('Ersätt befintligt hus','house-replace','primary')}${btn('Behåll befintliga hus','house-cancel','outline')}</section>`:''}${error?`<div class="notice warning" role="alert">${esc(error)}</div>`:''}</div>${message?`<p class="live-message" role="status">${esc(message)}</p>`:''}`;}
function renderPanel(){const scroll=$('.panel-body')?.scrollTop||0,saved=captureFocus(),p=$('.panel');if(p)p.innerHTML=panelHTML();if($('.panel-body'))$('.panel-body').scrollTop=scroll;restoreFocus(saved);positionChordTools();}
function render(){const saved=captureFocus(),scroll=$('.scene')?.scrollTop||0,panelScroll=$('.panel-body')?.scrollTop||0;$('#app').innerHTML=`<div class="demo-strip"><strong>Harmis · hybridförslag</strong><a href="index.html">Design och bilder</a><span>Interaktiv mockup · ändringar stannar i minnet</span></div><div class="app-shell"><header class="header"><div class="row"><div class="grow"><div class="eyebrow">Bibliotek / Ackordblad</div><h1>${esc(model.title)}</h1><p class="hint">${esc(model.artist)} · Grundarrangemang</p></div><span class="hint small demo-description">Arbetsprototyp</span>${btn('Inställningar','tab:settings','outline')}${btn('Nollställ demo','reset','outline')}</div><div class="row meta"><span>Tonart <strong>${esc(model.key)}</strong></span><span>Taktart <strong>${esc(model.meter)}</strong></span><span>Tempo <strong>${model.tempo} bpm</strong></span><span class="grow"></span><span>${past.length?'Ändrat i minnet':'Demolåt'}</span></div></header><div class="toolbar">${[['chord','Ändra ackord'],['insert','Infoga'],['rhythm','Rytm'],['repeats','Repris & hus'],['layout','Layout']].map(([id,label])=>btn(label,'tool:'+id,'music-tool '+(tab==='music'&&tool===id?'active':''))).join('')}${btn('Musik','tab:music','mobile-only')}${btn('Form','tab:form','mobile-only')}${btn('Låt','tab:song','mobile-only')}<span class="spacer"></span>${btn('↶','undo','',`aria-label="Ångra" ${past.length?'':'disabled'}`)}${btn('↷','redo','',`aria-label="Gör om" ${future.length?'':'disabled'}`)}</div><div class="content"><main class="preview"><div class="preview-top"><span>Redigera i bladet</span><span>${rangeAnchor!==null?'Välj sista takten i samma del':selected.length?selectionText():'Klick markerar ackord · klick igen redigerar'}</span>${selected.length&&!selectedPart&&!draft&&!chordId?btn(rangeAnchor!==null?'Avbryt markering':'Markera flera',rangeAnchor!==null?'range-cancel':'range-start','range-button'):''}</div><div class="scene"><article class="paper" aria-label="Redigerbart ackordblad">${scoreHTML()}</article></div><footer class="footer"><span>${draft?'Enter sparar · Escape avbryter · klick utanför sparar':'Klick markerar ackord · klick igen redigerar'}</span><span class="desktop-help">Shift + klick markerar takter · ⌘/Ctrl + Z ångrar</span></footer></main><div class="panel-scrim ${panelOpen?'open':''}" data-action="close-panel"></div><aside class="panel ${panelOpen?'open':''}" aria-label="Verktygspanel" tabindex="-1">${panelHTML()}</aside></div></div>${deletePartDialog()}`;$('.scene').scrollTop=scroll;$('.panel-body').scrollTop=panelScroll;restoreFocus(saved);positionChordTools();if(pendingPart){$('.delete-part-dialog').showModal();$('.delete-part-dialog [autofocus]').focus();}}
function openPanel(){panelOpen=true;if(innerWidth<761){returnFocus=document.activeElement;render();$('.panel').focus();}}
function setTool(next){const same=tab==='music'&&tool===next;if(!commitDraft())return;tab='music';tool=next;error='';panelOpen=true;render();if(!same)$('.panel-body').scrollTop=0;if(innerWidth<761)$('.panel').focus();}
function needBar(){if(!selectedBar()){fail('Välj först en takt i bladet.');return false;}return true;}
function setChordStart(id,value){const b=selectedBar(),i=b.chords.findIndex(c=>c.id===Number(id)),start=Number(value);if(i<0||start<1||(i>0&&start<=b.chords[i-1].start)||(b.chords[i+1]&&start>=b.chords[i+1].start)||start>=meterUnits(b)+1)return fail('Ackordbyten måste ligga i ordning, utan samma startpunkt.');mutate(()=>b.chords[i].start=start,'Ackordbytet placerades på slag '+beatLabel(start)+'.');}
function attacksValid(b,attacks){return attacks.every(a=>a.start>=1&&a.start+denominator(b)/a.duration<=meterUnits(b)+1&&attacks.every(other=>other===a||a.start+denominator(b)/a.duration<=other.start||other.start+denominator(b)/other.duration<=a.start));}
function moveBlock(id,newIndex){const index=model.form.findIndex(b=>b.id===id);if(newIndex<0||newIndex>=model.form.length)return;const next=clone(model.form),[moving]=next.splice(index,1);next.splice(newIndex,0,moving);const previous=model.form;model.form=next;const invalid=visibleBars().some(b=>b.chords.some(c=>c.start>=meterUnits(b)+1)||!attacksValid(b,b.attacks));model.form=previous;if(invalid){fail('Flytten skulle ändra ärvd taktart och placera ackord eller anslag utanför en takt. Ange ett lokalt taktartsbyte först.');return;}mutate(()=>model.form=next,'Låtformens ordning uppdaterades.');}
document.addEventListener('click',e=>{
 if(e.target.matches('#part-name,#score-edit,#panel-chords,#variant,#variant-pass,#variant-voice,input[name="text-behavior"]'))return;
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(e.target.closest('.chord-tools')&&!action)return;
 if(action?.startsWith('variant-choice:')){const choice=action.split(':')[1];if(choice==='edit'){delete draft.variantChanges;panelOpen=false;render();focusDraft(false);return;}commitDraft(true,choice);return;}
 if(action==='part-rename-cancel'){renameState=null;render();return;}
 if(action==='part-rename-save'){commitRename();return;}
 if(renameState&&!commitRename())return;
 const bar=e.target.closest('[data-bar]');if(bar&&!action){const id=Number(bar.dataset.bar),strip=e.target.closest('[data-select-bar]'),chord=e.target.closest('[data-chord]');if(strip||rangeAnchor!==null||e.shiftKey){selectBar(id,e.shiftKey);return;}if(chord){selectChord(id,Number(chord.dataset.chord),clickCaret(chord,e.clientX));return;}if(e.target.closest('[data-chord-area]')||!barById(id).chords.length)beginEdit(id,null);else selectBar(id);return;}
 if(draft&&!commitDraft(false))return;
 if(!action)return;
 if(action?.startsWith('select-part:')){selectPart(action.slice(12));return;}
 if(action?.startsWith('rename-part:')){const part=sectionById(action.slice(12));renameState={id:part.id,value:part.name,error:''};render();$('#part-name').focus();$('#part-name').select();return;}
 if(action?.startsWith('delete-part:')){requestDeletePart(action.slice(12));return;}
 if(action==='part-delete-confirm'){if(pendingPart)deletePart(pendingPart);return;}
 if(action==='part-delete-cancel'){const id=pendingPart;pendingPart=null;render();$(`[data-action="delete-part:${id}"]`)?.focus({preventScroll:true});return;}
 if(action?.startsWith('chord-step:')){const [,id,direction]=action.split(':'),b=selectedBar(),c=b.chords.find(c=>c.id===Number(id)),start=nextChordPosition(b,c,Number(direction));if(start!=null)setChordStart(id,start);return;}
 if(action==='range-start'){rangeAnchor=selected[0];panelOpen=false;message='Välj sista takten i samma del.';render();return;}
 if(action==='range-cancel'){rangeAnchor=null;message='Spannmarkeringen avbröts.';render();return;}
 if(action.startsWith('delete-bar:')){deleteBar(Number(action.split(':')[1]));return;}
 if(action.startsWith('duplicate-bar:')){duplicateBars([Number(action.split(':')[1])]);return;}
 if(action==='detach-reuse'){detachReuse();return;}
 if(action==='house-replace'){if(pendingHouse)applyHouse(pendingHouse.number);return;}
 if(action==='house-cancel'){pendingHouse=null;renderPanel();return;}
 if(action==='reset'){model=initial();past=[];future=[];selected=[];chordId=null;draft=null;rangeAnchor=null;pendingHouse=null;pendingPart=null;selectedPart=null;renameState=null;liveUndoKey=null;tab='music';tool='';panelOpen=false;message='';error='';render();return;}
 if(action==='undo'||action==='redo'){liveUndoKey=null;const from=action==='undo'?past:future,to=action==='undo'?future:past;if(from.length){to.push(clone(model));model=from.pop();renameState=null;if(!sectionById(selectedPart))selectedPart=null;if(selectedPart)selected=sectionById(selectedPart).bars.map(b=>b.id);selected=selected.filter(id=>barById(id));if(chordId&&!model.sections.some(s=>s.bars.some(b=>b.chords.some(c=>c.id===chordId))))chordId=null;message=action==='undo'?'Ändringen ångrades.':'Ändringen gjordes om.';error='';render();}return;}
 if(action.startsWith('tab:')){tab=action.slice(4);error='';panelOpen=true;render();$('.panel-body').scrollTop=0;if(innerWidth<761)$('.panel').focus();return;}
 if(action.startsWith('tool:')){setTool(action.slice(5));return;}
 if(action==='close-panel'){panelOpen=false;render();returnFocus?.focus?.();return;}
 if(action==='continue-edit'){if(needBar()){panelOpen=false;beginEdit(selected[0],chordId);}return;}
 if(action.startsWith('resolution:')){resolution=Number(action.slice(11));renderPanel();return;}
 if(action.startsWith('recent:')){addRecent(action.slice(7));return;}
 if(action==='nc'){if(!needBar())return;const b=selectedBar(),c=currentChord();beginEdit(b.id,c?.id);draft.value='N.C.';$('#score-edit').value='N.C.';commitDraft();return;}

 if(action.startsWith('chord-up:')){const b=selectedBar(),i=b.chords.findIndex(c=>c.id===Number(action.slice(9)));if(i<1)return;mutate(()=>{const a=b.chords[i-1],z=b.chords[i],start=a.start;a.start=z.start;z.start=start;b.chords.splice(i-1,2,z,a);},'Ackordens ordning ändrades. Startpunkterna ligger kvar.');return;}
 if(action.startsWith('attack:')){if(!needBar())return;const b=selectedBar(),start=Number(action.slice(7)),existing=b.attacks.find(a=>a.start===start);let next=existing?b.attacks.filter(a=>a!==existing):[...b.attacks,{start,duration:resolution}];if(!attacksValid(b,next))return fail('Anslaget överlappar ett annat anslag. Välj ett kortare notvärde först.');mutate(()=>b.attacks=next,existing?'Anslaget togs bort.':'Anslaget lades till.');return;}
 if(action.startsWith('house:')){if(!needBar())return;setTool(action);return;}
 if(action==='house-apply'){const value=$('#house-number').value.trim();if(!/^\d+(?:\s*,\s*\d+)*$/.test(value))return fail('Skriv husnummer, till exempel 1 eller 1, 2.');const overlaps=visibleBars().filter(b=>b.houseSpan?.barIds.some(id=>selected.includes(id)));if(overlaps.some(b=>JSON.stringify(b.houseSpan.barIds)!==JSON.stringify(selected))){pendingHouse={number:value,spans:overlaps.map(b=>clone(b.houseSpan))};renderPanel();return;}applyHouse(value);return;}
 if(action==='house-remove'){if(!needBar())return;mutate(()=>visibleBars().filter(b=>b.houseSpan?.barIds.some(id=>selected.includes(id))).forEach(b=>b.houseSpan=null),'Hela huset togs bort.');return;}
 if(action.startsWith('repeat:')){if(!needBar())return;const type=action.slice(7);mutate(()=>{if(type!=='end')barById(selected[0]).repeatStart=true;if(type!=='start')barById(selected.at(-1)).repeatEnd=true;},'Repristecknen visas i bladet.');return;}
 if(action.startsWith('block:')){selectedBlock=action.slice(6);error='';renderPanel();return;}
 if(action==='reuse'){const original=selectedForm();if(!original||original.reuse)return;const block={id:'reuse'+(++uid),source:original.source,reuse:true,count:1,instruction:''};mutate(()=>{const source=sectionById(original.source);if(source.bars.length){source.entryMeter=meterFor(source.bars[0]);if(!source.bars[0].meter)source.bars[0].meter=source.entryMeter;}model.form.push(block);selectedBlock=block.id;},'Delen återanvänds sist i formen. Flytta blocket till önskad plats.');return;}
 if(action==='reuse-apply'){const block=selectedForm(),count=Number($('#reuse-count').value),instruction=$('#reuse-instruction').value.trim();if(!Number.isInteger(count)||count<1||count>16)return fail('Välj ett heltal mellan 1 och 16.');mutate(()=>{block.count=count;block.instruction=instruction;},'Återanvändningens inställningar uppdaterades.');return;}
 if(action==='reuse-remove'){const block=selectedForm();if(!block?.reuse)return;mutate(()=>{model.form=model.form.filter(b=>b!==block);selectedBlock=sourceBlock(block).id;},'Återanvändningen togs bort.');return;}
 if(action.startsWith('move:')){const [,id,delta]=action.split(':');moveBlock(id,model.form.findIndex(b=>b.id===id)+Number(delta));return;}
 if(action.startsWith('goto-source:')){$('#section-'+action.slice(12))?.scrollIntoView({block:'start'});panelOpen=false;render();return;}
 if(action==='duplicate-bars'){if(needBar())duplicateBars([...selected]);return;}
 if(action==='insert-bar'){if(!needBar())return;const section=sectionOf(selected[0]),index=section.bars.findIndex(b=>b.id===selected.at(-1));mutate(()=>{const spans=section.bars.filter(b=>b.houseSpan).map(owner=>({owner,first:owner.houseSpan.barIds[0],last:owner.houseSpan.barIds.at(-1)}));const bars=action==='insert-bar'?[makeBar([])]:selected.map(id=>{const b=clone(barById(id));b.id=++uid;b.houseSpan=null;b.chords.forEach(c=>c.id=++uid);return b;});section.bars.splice(index+1,0,...bars);for(const span of spans){const first=section.bars.findIndex(b=>b.id===span.first),last=section.bars.findIndex(b=>b.id===span.last);span.owner.houseSpan.barIds=section.bars.slice(first,last+1).map(b=>b.id);span.owner.houseSpan.length=span.owner.houseSpan.barIds.length;}},action==='insert-bar'?'En tom takt lades till.':'Markerade takter duplicerades.');return;}
 if(action.startsWith('break:')){if(!needBar())return;const b=selectedBar(),type=action.slice(6);mutate(()=>{b.rowBreak=type==='row';b.pageBreak=type==='page';},'Brytningen uppdaterades i bladet.');return;}
 if(action==='local-apply'){if(!needBar())return;const b=selectedBar(),key=$('#local-key').value,meter=$('#local-meter').value,oldKey=b.key,oldMeter=b.meter;b.key=key;b.meter=meter;const invalid=model.sections.flatMap(s=>s.bars).some(bar=>bar.chords.some(c=>c.start>=meterUnits(bar)+1)||!attacksValid(bar,bar.attacks));b.key=oldKey;b.meter=oldMeter;if(invalid)return fail('Taktarten skulle placera ackord eller anslag utanför takten. Flytta dem först.');mutate(()=>{b.key=key;b.meter=meter;},'Lokala byten visas i bladet.');return;}
 if(action==='song-apply'){const title=$('#song-title').value.trim(),artist=$('#song-artist').value.trim(),key=$('#song-key').value.trim(),tempo=Number($('#song-tempo').value),meter=$('#song-meter').value,status=$('#song-status').value,version=$('#song-version').value.trim();if(!title||!/^[A-G](?:#|b|♯|♭)?m?$/.test(key)||!Number.isFinite(tempo)||tempo<20||tempo>300)return fail('Ange titel, tonart och tempo mellan 20 och 300.');const old=model.meter;model.meter=meter;const invalid=visibleBars().some(b=>b.chords.some(c=>c.start>=meterUnits(b)+1)||!attacksValid(b,b.attacks));model.meter=old;if(invalid)return fail('Grundtaktarten skulle placera ackord eller anslag utanför en takt. Flytta dem först.');mutate(()=>Object.assign(model,{title,artist,key,tempo,meter,status,version}),'Låtuppgifterna uppdaterades.');return;}
});
document.addEventListener('focusout',e=>{if(e.target.id==='part-name'&&renameState){const pending=renameState;setTimeout(()=>{if(renameState===pending&&document.activeElement?.id!=='part-name')commitRename();},0);}if(['variant','variant-pass','variant-voice','variant-following'].includes(e.target.id))liveUndoKey=null;if(['score-edit','panel-chords'].includes(e.target.id)&&draft){const pending=draft;setTimeout(()=>{if(draft===pending&&!['score-edit','panel-chords'].includes(document.activeElement?.id))commitDraft(false);},0);}});
document.addEventListener('input',e=>{
 if(e.target.id==='part-name'&&renameState){renameState.value=e.target.value;renameState.error='';return;}
 if(['variant','variant-pass','variant-voice'].includes(e.target.id)){liveVariant();return;}
 if(e.target.id==='panel-chords'){const b=selectedBar();if(!b)return;if(!draft||draft.kind!=='panel')draft={barId:b.id,chordId:null,kind:'panel',original:serialize(b),error:''};draft.value=e.target.value;draft.error='';delete draft.variantChanges;return;}
 if(e.target.id==='score-edit'&&draft){draft.value=e.target.value;draft.error='';delete draft.variantChanges;}
});
document.addEventListener('change',e=>{
 if(e.target.id==='variant-following'){liveVariant();liveUndoKey=null;return;}
 if(e.target.hasAttribute('data-chord-grid')){if(draft&&!commitDraft(false))return;resolution=Number(e.target.value);renderScore();renderPanel();return;}
 if(e.target.name==='text-behavior'){preferences.selectAll=e.target.value==='select';try{localStorage.setItem('harmis-editor-preferences',JSON.stringify(preferences));}catch{}message='Inställningen gäller nästa gång du öppnar ackordtext.';renderPanel();return;}
 if(e.target.dataset.start){setChordStart(e.target.dataset.start,e.target.value);return;}
 if(e.target.dataset.duration){const b=selectedBar(),start=Number(e.target.dataset.duration),duration=Number(e.target.value),next=b.attacks.map(a=>a.start===start?{...a,duration}:a);if(!attacksValid(b,next))return fail('Notvärdet överlappar nästa anslag eller går förbi taktens slut.');mutate(()=>b.attacks=next,'Anslagets notvärde ändrades.');}
});
document.addEventListener('keydown',e=>{
 if(e.target.id==='part-name'){if(e.isComposing)return;if(e.key==='Enter'){e.preventDefault();commitRename();}if(e.key==='Escape'){e.preventDefault();renameState=null;render();}return;}
 if(['score-edit','panel-chords'].includes(e.target.id)){if(e.isComposing)return;if(e.key==='Enter'){e.preventDefault();commitDraft();}if(e.key==='Escape'){e.preventDefault();draft=null;panelOpen=false;message='Textändringen avbröts.';render();}return;}
 if(e.key==='Escape'&&pendingPart){e.preventDefault();pendingPart=null;render();return;}
 if(e.key==='Escape'){rangeAnchor=null;pendingHouse=null;if(panelOpen&&innerWidth<761){panelOpen=false;render();}else{selected=[];chordId=null;selectedPart=null;renameState=null;error='';render();}return;}
 if(e.target.matches('input,textarea,select'))return;
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();document.querySelector(`[data-action="${e.shiftKey?'redo':'undo'}"]`).click();return;}
 if(e.target.closest('button'))return;
 const bar=e.target.closest('[data-bar]');if(bar&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(e.target.closest('[data-select-bar]'))selectBar(Number(bar.dataset.bar),e.shiftKey);else if(e.target.dataset.chord)selectChord(Number(bar.dataset.bar),Number(e.target.dataset.chord));else beginEdit(Number(bar.dataset.bar),null);}
});
let dragging='';document.addEventListener('dragstart',e=>{const block=e.target.closest('[data-block]');if(block){dragging=block.dataset.block;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragging);}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-block]'))e.preventDefault();});document.addEventListener('drop',e=>{const block=e.target.closest('[data-block]');if(block&&dragging){e.preventDefault();moveBlock(dragging,model.form.findIndex(b=>b.id===block.dataset.block));dragging='';}});
window.hybrid={getState:()=>clone({model,selected,chordId,draft,tab,tool,panelOpen,resolution,pastCount:past.length,futureCount:future.length,message,error,preferences,rangeAnchor,pendingHouse,pendingPart,selectedPart,renameState}),select:(section,index)=>beginEdit(sectionById(section).bars[index].id,null),reset:()=>{model=initial();past=[];future=[];selected=[];chordId=null;selectedPart=null;renameState=null;draft=null;rangeAnchor=null;pendingHouse=null;render();}};
render();

document.fonts.ready.then(positionChordTools);
window.addEventListener('resize',positionChordTools);
